	float SparkPerDamage = 0.f;

	UPROPERTY()
	float SparkMinRadius = 0.f;

	UPROPERTY()
	float SparkMaxRadius = 0.f;

	/** A hit on the Publisher of this damage or more flashes him fully white; a smaller one only tints him. */
