#include "UI/JamMarkerRules.h"

FJamEdgeMarker JamMarkerRules::EdgeMarker(const FVector2D& Target, const FVector2D& ViewSize, float Margin)
{
	FJamEdgeMarker Marker;
	const FVector2D Centre = 0.5 * ViewSize;
	const FVector2D Reach = FVector2D(FMath::Max(1.0, Centre.X - Margin), FMath::Max(1.0, Centre.Y - Margin));
	const FVector2D Away = Target - Centre;
	if (FMath::Abs(Away.X) <= Reach.X && FMath::Abs(Away.Y) <= Reach.Y)
	{
		return Marker;
	}
	// Walk from the centre towards the point until the first inset edge: the arrow sits where the eye looks for him.
	const double ScaleX = FMath::Abs(Away.X) > UE_KINDA_SMALL_NUMBER ? Reach.X / FMath::Abs(Away.X) : UE_BIG_NUMBER;
	const double ScaleY = FMath::Abs(Away.Y) > UE_KINDA_SMALL_NUMBER ? Reach.Y / FMath::Abs(Away.Y) : UE_BIG_NUMBER;
	Marker.bShow = true;
	Marker.Pos = Centre + Away * FMath::Min(ScaleX, ScaleY);
	Marker.Angle = FMath::RadiansToDegrees(FMath::Atan2(Away.Y, Away.X));
	return Marker;
}

