/**
 * The retry point. A death does not send the player to the start: the fight comes back as it stood after the last
 * steal, with the boss's health and the ledger of that moment, the hero healed and both fighters on their marks.
 * Tests: Jam.Retry.*
 */
namespace JamCheckpointRules
{
/** What a retry starts from, taken from the fight as it stands now. */
JAMGAME_API FJamFight Capture(const FJamFight& Fight, const FJamBalanceData& Balance);

/** A fight that starts from the saved point with new luck. */
JAMGAME_API FJamFight Restore(const FJamFight& Saved, int32 Seed);
} // namespace JamCheckpointRules
#include "Sim/JamCheckpointRules.h"

#include "Sim/JamFightRules.h"

FJamFight JamCheckpointRules::Capture(const FJamFight& Fight, const FJamBalanceData& Balance)
{
	// A fresh fight with what must survive a death: nothing in the air, no timers, the hero whole.
	FJamFight Saved = JamFightRules::Start(Balance, 0);
	Saved.Fighters[EJamSide::Boss].Health = Fight.Fighters[EJamSide::Boss].Health;
	Saved.Ledger = Fight.Ledger;
	Saved.Steal.Done = Fight.Steal.Done;
	Saved.Steal.Floor = Fight.Steal.Floor;
	return Saved;
}

FJamFight JamCheckpointRules::Restore(const FJamFight& Saved, int32 Seed)
{
	FJamFight Fight = Saved;
	Fight.Stream.Initialize(Seed);
	return Fight;
}
